void thaydoi(int n){
    n += 100;
}

int main(void){
    int m = 1000;
    thaydoi(m);
    printf("%d\n", m);   // vẫn là 1000
}

void thaydoi(int *n){
    *n += 100;
}

int main(void){
    int m = 1000;
    thaydoi(&m);          // truyền địa chỉ
    printf("%d\n", m);   // thành 1100
}

void swap1(int a, int b){        // tham trị: vô ích
    int tmp = a; a = b; b = tmp;
}

void swap2(int *a, int *b){      // con trỏ: đúng
    int tmp = *a; *a = *b; *b = tmp;
}

int x = 100, y = 200;
swap1(x, y);     // 100 200
swap2(&x, &y);   // 200 100

int chia(int a, int b, int *thuong, int *du){
    if(b == 0) return 0;          // thất bại
    *thuong = a / b;
    *du = a % b;
    return 1;                     // thành công
}

int q, r;
if(chia(17, 5, &q, &r)) printf("%d %d\n", q, r);  // 3 2
